package com.tripmateai.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*;
@Entity @Table(name="favorites",uniqueConstraints={@UniqueConstraint(name="uk_favorite_destination",columnNames={"user_id","destination_id"}),@UniqueConstraint(name="uk_favorite_hotel",columnNames={"user_id","hotel_id"}),@UniqueConstraint(name="uk_favorite_restaurant",columnNames={"user_id","restaurant_id"}),@UniqueConstraint(name="uk_favorite_attraction",columnNames={"user_id","attraction_id"})}) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class Favorite extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="destination_id") @ToString.Exclude private Destination destination; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="hotel_id") @ToString.Exclude private Hotel hotel; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="restaurant_id") @ToString.Exclude private Restaurant restaurant; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="attraction_id") @ToString.Exclude private Attraction attraction; }
